from mk import *
from lib import fbd
STRICT["on"] = True

def fig():
    g = Fig(560, 280, "תרשים 1: שתי תיבות A (300 גרם) ו-B (100 גרם) על משטח חלק, וביניהן קפיץ מכווץ, וחוט מחבר את המוטות שעליהן. משמאל מדרון שעולה לנקודה C בגובה hC. תרשים 2: שלושה מצבים אפשריים של מטוטלת קטנה על תיבה A")
    g.path("M 40,30 L 200,170 L 520,170", width=2.5)
    g.dot(90, 74); g.text(98, 66, "C", anchor="start"); g.dim(70, 74, 70, 170, "hC", offset=0)
    g.block(330, 152, 40, 34, "A"); g.spring(350, 160, 380, 160, coils=4, amp=5); g.block(400, 152, 40, 34, "B")
    g.line(330, 135, 330, 110, width=1.5); g.line(400, 135, 400, 110, width=1.5); g.path("M 330,112 Q 365,100 400,112", width=1.5)
    for i, (lab, dx) in enumerate((("III", 1), ("II", -1), ("I", 0))):
        ox = 150 + i * 110; g.rect(ox, 200, 80, 64, fill="none", width=1.2)
        g.block(ox + 40, 252, 30, 22, "A", fill="var(--d-fill)", text_color="var(--d-label)")
        g.line(ox + 40, 241, ox + 40, 216, width=1.5)
        g.line(ox + 40, 216, ox + 40 + dx * 12, 230 if dx else 236, width=1.2); g.circle(ox + 40 + dx * 12, 233 if dx else 239, 4, fill="none", stroke="var(--d-line)")
        g.text(ox + 40, 278, lab, cls="dim")
    return g

E(id="bagrut-2017-q3", year=2017, label="2017 שאלה 3", topic="momentum", sub="mom-conservation", diff=3, fig=fig,
  stem=r"שתי תיבות, $A$ שמסתה $m_A = 300\,\text{g}$ ו-$B$ שמסתה $m_B = 100\,\text{g}$, עומדות על משטח אופקי חלק. ביניהן יש קפיץ קל מכווץ. על כל תיבה יש מוט, וחוט שקשור לשני המוטות לא נותן לתיבות לזוז. קבוע הקפיץ $K = 480\,\text{N/m}$. אורך הקפיץ המכווץ $10\,\text{cm}$, והאורך הרפוי שלו $20\,\text{cm}$. ברגע מסוים החוט נקרע, והקפיץ דוחף את התיבות לצדדים מנוגדים. אחרי הדחיפה התיבות נעות במהירויות קבועות שגודלן $u_A$ ו-$u_B$, והקפיץ נופל אנכית לרצפה. בסעיפים א ו-ב מתייחסים למערכת של שתי התיבות והקפיץ, מהרגע שהחוט נקרע עד שהתיבות עוזבות את הקפיץ.",
  parts=[
    P("א", r"האם התנע של המערכת נשמר בזמן הזה? נמקו.", choice(["כן", "לא"], 0), ["principle"], [
        S(r"הכוחות", r"כוח הקפיץ הוא פנימי למערכת. המשטח חלק, ולכן אין כוח חיצוני אופקי", r"\Sigma F_x = 0 \;\Rightarrow\; \Delta p = 0"),
    ], r"כן: פועלים רק כוחות פנימיים", key=r"כן"),
    P("ב", r"האם האנרגיה המכנית של המערכת נשמרת בזמן הזה? נמקו.", choice(["כן", "לא"], 0), ["principle"], [
        S(r"אין חיכוך", r"כל האנרגיה האלסטית של הקפיץ הופכת לאנרגיה קינטית של התיבות", r"U_{sp} \to E_k"),
    ], r"כן", key=r"כן"),
    P("ג1", r"מה גודל המהירות $u_A$?", num(2, "m/s"), ["principle", "algebra"], [
        S(r"האנרגיה בקפיץ", r"הכיווץ הוא ההפרש בין האורך הרפוי לאורך המכווץ, עשרה סנטימטרים", r"U_{sp} = \tfrac{1}{2} \cdot 480 \cdot 0.1^2 = 2.4\,\text{J}", eq=r"U_{sp} = \tfrac{1}{2}K(\Delta\ell)^2"),
        S(r"שימור תנע", r"התיבות התחילו במנוחה, ולכן התנעים שלהן שווים בגודלם", r"0.3\,u_A = 0.1\,u_B \;\Rightarrow\; u_B = 3\,u_A", eq=r"m_A\vec v_A + m_B\vec v_B = m_A\vec u_A + m_B\vec u_B"),
        S(r"שימור אנרגיה", r"מציבים את הקשר בין המהירויות", r"\tfrac{1}{2} \cdot 0.3\,u_A^2 + \tfrac{1}{2} \cdot 0.1 \cdot 9\,u_A^2 = 2.4 \;\Rightarrow\; 0.6\,u_A^2 = 2.4", eq=r"E_k = \tfrac{1}{2}mv^2"),
        S(r"פותרים", r"מוציאים שורש", r"u_A = \sqrt{4} = 2\,\text{m/s}"),
    ], r"$2\,\text{m/s}$", key=r"uA=2 m/s"),
    P("ג2", r"מה גודל המהירות $u_B$?", num(6, "m/s"), ["principle"], [
        S(r"מהקשר", r"מהסעיף הקודם, המהירות של התיבה הקלה גדולה פי שלושה", r"u_B = 3 \cdot 2 = 6\,\text{m/s}"),
    ], r"$6\,\text{m/s}$", key=r"uB=−6 m/s"),
    P("ד", r"בשלב מסוים התיבה $A$ מגיעה למדרון. היא עולה עד הנקודה $C$, שגבוהה ב-$h_C = 0.1\,\text{m}$ מעל המשטח האופקי, וגולשת חזרה. הוכיחו שהמדרון לא חלק.", OPEN, ["principle"], [
        S(r"האנרגיה בתחתית המדרון", r"מהירות התיבה מהסעיף הקודם", r"E_k = \tfrac{1}{2} \cdot 0.3 \cdot 2^2 = 0.6\,\text{J}", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
        S(r"האנרגיה בנקודה C", r"שם התיבה נעצרת, ולכן יש לה רק אנרגיית גובה", r"U_G = 0.3 \cdot 10 \cdot 0.1 = 0.3\,\text{J}"),
        S(r"מסקנה", r"חלק מהאנרגיה המכנית אבד בדרך. רק כוח חיכוך יכול לעשות את זה", r"W_{\text{nc}} = 0.3 - 0.6 = -0.3\,\text{J} \ne 0", eq=r"W_{\text{nc}} = \Delta E"),
    ], r"בתחתית $0.6\,\text{J}$, ובשיא רק $0.3\,\text{J}$: חצי מהאנרגיה אבד לחיכוך", key=r"E=0.6J בהתחלה ; E=0.3J בסוף"),
    P("ה", r"אחרי שהקפיץ נפל, בזמן שהתיבה $A$ נעה על המשטח האופקי, תולים על המוט שלה מטוטלת קטנה, בלי להשפיע על תנועת התיבה. תרשים 2 מראה שלושה איורים, I עד III. איזה איור מתאר נכון את המטוטלת בזמן שהתיבה נעה על המשטח האופקי? הסבירו.", choice(["I", "II", "III"], 0), ["principle"], [
        D(r"תרשים הכוחות על המשקולת של המטוטלת", lambda: fbd([("T", 90, 0.6), ("mg", -90, 0.6)],
            "תרשים כוחות על המשקולת של המטוטלת: מתיחות החוט כלפי מעלה וכוח הכובד כלפי מטה", body="ball")),
        S(r"מהירות קבועה", r"התיבה נעה במהירות קבועה, ולכן גם המשקולת. אין לה תאוצה, ולכן הכוח השקול עליה אפס. המתיחות חייבת לאזן את הכובד, ולכן החוט אנכי", r"T - mg = m \cdot 0", eq=r"\Sigma\vec F = m\vec a"),
    ], r"איור I: החוט אנכי", key=r"גרף I"),
  ],
  concepts=["שימור תנע", "שימור אנרגיה", "אנרגיה אלסטית", "עבודת חיכוך", "מטוטלת בתנועה במהירות קבועה"],
  summary=r"קפיץ שדוחף שתי תיבות: מהירויות משימור תנע ואנרגיה, הוכחה שיש חיכוך במדרון, ומטוטלת שתלויה אנכית בתנועה במהירות קבועה.",
  review="הנחה שלי.\nמה לבדוק: רק לאשר.")
